-- 0023: 인기 검색어 RPC. 이미 운영 DB 에 적용됨 — 다시 적용하지 말 것 (이 파일은 저장소 기록용).
create or replace function public.popular_searches(p_days int default 60, p_limit int default 300) returns table(term text, n bigint) language sql stable security definer set search_path = public as $$ select key as term, sum(n)::bigint as n from stat_daily where event = 'search' and day >= (now() at time zone 'Asia/Seoul')::date - greatest(1, least(p_days, 365)) and char_length(key) between 1 and 20 group by key having sum(n) >= 2 order by sum(n) desc limit greatest(1, least(p_limit, 500)); $$; revoke all on function public.popular_searches(int, int) from public; grant execute on function public.popular_searches(int, int) to anon, authenticated;
